#include <iostream>
#include <string>
#include <sstream>
#include <algorithm>

int main() {
    int n;
    std::cin >> n;
    std::cin.ignore(); // ignore the newline after the integer input
    std::string s;
    std::getline(std::cin, s);
    // Replace all sequences of underscores with a space
    std::string result;
    bool inUnderscoreSeq = false;
    for (char c : s) {
        if (c == '_') {
            if (!inUnderscoreSeq) {
                result += ' ';
                inUnderscoreSeq = true;
            }
        } else {
            result += c;
            inUnderscoreSeq = false;
        }
    }
    // Insert spaces around parentheses
    std::string sb;
    for (char c : result) {
        if (c == '(') {
            sb += " ( ";
        } else if (c == ')') {
            sb += " ) ";
        } else {
            sb += c;
        }
    }
    // Split the string into tokens based on whitespace
    std::istringstream iss(sb);
    std::string token;
    int maxLen = 0;
    int countParen = 0;
    bool inParen = false;
    while (iss >> token) {
        if (token.find('(') != std::string::npos) {
            inParen = true;
        } else if (token.find(')') != std::string::npos) {
            inParen = false;
        } else if (token.find('(') == std::string::npos && token.find(')') == std::string::npos) {
            if (inParen) {
                countParen++;
            } else {
                maxLen = std::max(maxLen, static_cast<int>(token.length()));
            }
        }
    }
    std::cout << maxLen << " " << countParen << std::endl;
    return 0;
}
